// Binary search - array MUST be sorted
int binarySearch(int[] arr, int target) {
    int low = 0, high = arr.length - 1;

    while (low <= high) {
        int mid = (low + high) / 2;
        if (arr[mid] == target) {
            return mid; // found
        } else if (arr[mid] < target) {
            low = mid + 1;  // search the right half
        } else {
            high = mid - 1; // search the left half
        }
    }
    return -1; // not found
}

// binarySearch({1,3,5,7,9,11}, 7) -> 3 (index of value 7)

void bubbleSort(int[] arr) {
    int n = arr.length;
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                // swap
                int temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }
}

// Example: {5, 2, 8, 1, 9} -> {1, 2, 5, 8, 9}

void mergeSort(int[] arr, int left, int right) {
    if (left >= right) return; // base case: 1 element is already "sorted"

    int mid = (left + right) / 2;
    mergeSort(arr, left, mid);       // sort left half
    mergeSort(arr, mid + 1, right);  // sort right half
    merge(arr, left, mid, right);    // merge the two sorted halves
}

void merge(int[] arr, int left, int mid, int right) {
    int[] temp = new int[right - left + 1];
    int i = left, j = mid + 1, k = 0;

    while (i <= mid && j <= right) {
        temp[k++] = (arr[i] <= arr[j]) ? arr[i++] : arr[j++];
    }
    while (i <= mid) temp[k++] = arr[i++];
    while (j <= right) temp[k++] = arr[j++];

    System.arraycopy(temp, 0, arr, left, temp.length);
}
// Splits {5,2,8,1,9} down to single elements, then merges them back in sorted order

