// [[], [3], [2], [2, 3], [1], [1, 3], [1, 2], [1, 2, 3]]

public class NQueensDemo {

    static int count = 0;

    static boolean isSafe(int[] board, int row, int col) {
        for (int i = 0; i < col; i++) {
            int placedRow = board[i];
            if (placedRow == row || Math.abs(placedRow - row) == Math.abs(i - col)) {
                return false; // same row or same diagonal
            }
        }
        return true;
    }

    static void solve(int[] board, int col, int n) {
        if (col == n) {
            count++; // found one valid full placement
            return;
        }

        for (int row = 0; row < n; row++) {
            if (isSafe(board, row, col)) {
                board[col] = row;        // CHOOSE
                solve(board, col + 1, n); // EXPLORE
                // board[col] gets overwritten next iteration - implicit UN-CHOOSE
            }
        }
    }

    public static void main(String[] args) {
        int n = 4;
        int[] board = new int[n];
        solve(board, 0, n);

        System.out.println("Total solutions for " + n + "-Queens: " + count);
    }
}
// OUTPUT:
// Total solutions for 4-Queens: 2

public class NQueensPrintSolution {

    static boolean isSafe(int[] board, int row, int col) {
        for (int i = 0; i < col; i++) {
            if (board[i] == row || Math.abs(board[i] - row) == Math.abs(i - col)) {
                return false;
            }
        }
        return true;
    }

    static boolean solve(int[] board, int col, int n) {
        if (col == n) return true;

        for (int row = 0; row < n; row++) {
            if (isSafe(board, row, col)) {
                board[col] = row;
                if (solve(board, col + 1, n)) {
                    return true; // stop at first solution found
                }
                // implicit backtrack: loop continues to next row
            }
        }
        return false;
    }

    public static void main(String[] args) {
        int n = 4;
        int[] board = new int[n];
        solve(board, 0, n);

        for (int col = 0; col < n; col++) {
            for (int row = 0; row < n; row++) {
                System.out.print(board[col] == row ? "Q " : ". ");
            }
            System.out.println();
        }
    }
}
// OUTPUT:   (the search returns the FIRST solution, board = [1,3,0,2])
// . Q . .
// . . . Q
// Q . . .
// . . Q .

import java.util.ArrayList;
import java.util.List;

public class GreedyCoinChange {

    static List<Integer> makeChange(int[] coins, int amount) {
        List<Integer> result = new ArrayList<>();

        for (int i = coins.length - 1; i >= 0; i--) { // coins sorted ascending, go largest first
            while (amount >= coins[i]) {
                amount -= coins[i];
                result.add(coins[i]); // greedy pick: largest coin that fits
            }
        }
        return result;
    }

    public static void main(String[] args) {
        int[] coins = {1, 5, 10, 25}; // standard US-style coin denominations
        int amount = 63;

        List<Integer> change = makeChange(coins, amount);
        System.out.println("Coins used: " + change);
        System.out.println("Total coins: " + change.size());
    }
}
